import * as core from './measuring-desk-core.mjs';
import {measurementSource} from './measuring-desk-content.mjs';
import {hearButton} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,attr='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attr}>${esc(text)}</button>`;
let historyTurn={state:null,explorerId:null,page:0};
function historyPage(state,explorerId){if(historyTurn.state!==state||historyTurn.explorerId!==explorerId)historyTurn={state,explorerId,page:0};return historyTurn.page;}
function drawing(source){const d=source.drawing;return d.version===1&&d.kind==='eye-level'?`<figure class="measure-figure"><img src="measuring-desk-method-v1.svg" alt="${esc(d.description)}"><figcaption>${esc(d.description)}</figcaption></figure>`:`<p class="measure-figure-fallback">${esc(d.description)}</p>`;}
function credits(source){return `<details class="measure-credits"><summary>Grown-ups: background sources</summary><p>These references explain the method's limits; none certifies this jug or reading.</p><ul>${source.credits.map(c=>`<li><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.title)}</a>: ${esc(c.role)}</li>`).join('')}</ul></details>`;}
function method(source,compact=false){const c=source.copy;return `<section class="measure-method"><h2>With an adult and one real jug</h2><p>${esc(c.intro)}</p><p><strong>What you need:</strong> ${esc(c.materials)}</p>${drawing(source)}<ol>${c.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="measure-safety"><strong>Stay safe:</strong> ${esc(c.safety)}</p><p>${esc(c.missing)}</p><p><a href="#cafe/recipes">Use pictured practice</a> <a href="#field/jug">Read the real-jug card</a></p>${credits(source)}</section>`;}
function rawDisplay(raw,s){return `<dl class="measure-readings"><div><dt>${esc(s.labels.first)}</dt><dd>${esc(raw.first||'(blank)')} mL</dd></div><div><dt>${esc(s.labels.second)}</dt><dd>${esc(raw.second||'(blank)')} mL</dd></div><div><dt>${esc(s.labels.gap)}</dt><dd>${raw.gap.trim()===''?esc(s.copy.gapMissing):core.parseMeasurement(raw.gap)!==null&&core.parseMeasurement(raw.gap)>0?`${esc(raw.gap)} mL`:esc(s.copy.gapUnfinished)}</dd></div></dl>`;}
function result(c,{earlier=false}={}){if(!core.validMeasurementComparison(c))return '<p>This earlier comparison cannot be read. Its complete original data remains in Grown-up notes.</p>';const s=c.source,choice=c.choiceMatches===null?s.copy.noChoice:c.choiceMatches?s.copy.choiceFits:s.copy.choiceDifferent;return `<section class="measure-result"><h3>${earlier?'Earlier comparison':'Comparison of entered numbers'}</h3><p>First entered: ${esc(c.raw.first)} mL. Second entered: ${esc(c.raw.second)} mL.</p><p>${esc(c.summary)} The numerical difference is ${esc(core.formatMeasurement(c.difference))} mL.</p><p>${esc(choice)}</p><p>Gap between marks: ${c.raw.gap.trim()===''?esc(s.copy.gapMissing):core.parseMeasurement(c.raw.gap)!==null&&core.parseMeasurement(c.raw.gap)>0?`${esc(c.raw.gap)} mL`:esc(s.copy.gapUnfinished)}.</p><p>${esc(c.limit)}</p></section>`;}
function frozen(entry){const s=entry.snapshot,k=entry.id;return `<article class="measure-kept-entry" data-measure-entry="${k}"><h3>Kept version ${k}: ${esc(s.source.title)}</h3><p>${esc(s.source.copy.provenance)}</p>${rawDisplay(s.raw,s.source)}<p>Chosen relation: ${s.choice===null?'left blank':esc(s.source.copy.choices.find(c=>c.code===s.choice)?.label||s.choice)}. Support: ${s.support.length?esc(s.support.join(', ')):'none recorded'}.</p>${s.comparison===null?'<p>No comparison was kept with this version.</p>':result(s.comparison,{earlier:true})}${s.earlierRawComparisons?.length?`<p>${s.earlierRawComparisons.length} earlier comparison value(s) retained unchanged. Their original data is in Grown-up notes.</p>`:''}</article>`;}
function history(view,state,explorerId){const entries=view.entries,allPages=Math.max(1,Math.ceil(entries.length/8)),page=Math.min(historyPage(state,explorerId),allPages-1),end=entries.length-page*8,start=Math.max(0,end-8),shown=entries.slice(start,end).reverse();historyTurn.page=page;return `<details class="measure-history"><summary>Kept versions (${entries.length} readable)</summary>${shown.length?shown.map(x=>frozen(x.entry)).join(''):'<p>No kept version yet.</p>'}${allPages>1?`<nav aria-label="Older kept versions">${button('Newer kept versions','data-measure-history="newer"'+(page===0?' disabled':''))}<span>Page ${page+1} of ${allPages}</span>${button('Older kept versions','data-measure-history="older"'+(page===allPages-1?' disabled':''))}</nav>`:''}${view.rawEntries.length?`<p>${view.rawEntries.length} earlier entry or entries are unavailable here; their original data remains in the notes download.</p>`:''}</details>`;}
function recordTurn(d){const s=d.source;return `<section class="measure-turn"><h2 id="measure-turn-title" tabindex="-1">1. Record what you report</h2><p>${esc(s.copy.provenance)}</p>${drawing(s)}<div class="measure-reading-grid">${['first','second','gap'].map((key,i)=>`<label class="measure-reading-card"><strong>${i<2?`${i+1}. `:''}${esc(s.labels[key])}</strong><input data-measure-raw="${key}" type="text" inputmode="decimal" maxlength="24" autocomplete="off" spellcheck="false" value="${esc(d.raw[key])}"></label>`).join('')}</div><p>${esc(s.copy.precisionNote)}</p><p>${esc(s.copy.unitNote)}</p><fieldset><legend>${esc(s.copy.comparisonPrompt)}</legend>${s.copy.choices.map(c=>`<label class="measure-choice"><input type="radio" name="measure-choice" data-measure-choice="${c.code}" ${d.choice===c.code?'checked':''}><span>${esc(c.label)}</span></label>`).join('')}<label class="measure-choice"><input type="radio" name="measure-choice" data-measure-choice="" ${d.choice===null?'checked':''}><span>Leave our choice blank</span></label></fieldset><div class="measure-actions">${button('Compare our entries','data-measure-compare',true)}${button('Keep this version','data-measure-keep')}</div>${d.comparison!==null&&!core.currentMeasurementComparison(d)?`<p class="measure-earlier">${core.validMeasurementComparison(d.comparison)?'An earlier comparison belongs to a different draft or support state.': 'The current comparison cannot be read. The original value remains in notes.'}</p>`:''}${d.comparison!==null&&!core.validMeasurementComparison(d.comparison)?`<details data-measure-replace><summary>Keep earlier comparison and compare again</summary><p>This keeps the whole unreadable comparison unchanged as earlier raw data. A new comparison will use the current entries. Download notes first if you want another copy.</p>${button('Confirm: keep earlier comparison and compare again','data-measure-confirm-compare',true)}${button('Cancel','data-measure-cancel-compare')}</details>`:''}<p class="measure-format" id="measure-format" tabindex="-1"></p></section>`;}
function compareTurn(view){const d=view.draft;return `<section class="measure-turn"><h2 id="measure-turn-title" tabindex="-1">2. Compare only the entered numbers</h2><p>${esc(d.source.copy.provenance)}</p>${view.current?result(view.current):view.comparisonUnreadable?'<p>The current comparison cannot be read. Your exact entered readings remain in the Record turn. Keep this draft or explicitly save the earlier raw comparison before comparing again.</p>':d.comparison!==null?`${result(d.comparison,{earlier:true})}<p>That comparison belongs to an earlier draft or support state. Return to Record to compare the current entries.</p>`:'<p>No comparison has been made for this draft. Record two readings to compare their numbers.</p>'}<p>${esc(d.source.copy.reflection)}</p><p>${button('Keep this version','data-measure-keep')}${button('Revise our draft','data-measure-page="record"')}</p></section>`;}
function keptTurn(view){const d=view.draft,last=view.entries.at(-1)?.entry;return `<section class="measure-turn"><h2 id="measure-turn-title" tabindex="-1">3. Keep or change our draft</h2><p>A kept version stays as it was. Changes to this draft do not rewrite it.</p>${last?frozen(last):'<p>No version has been kept yet. You may keep a blank or unfinished draft.</p>'}<div class="measure-actions">${button('Revise our draft','data-measure-page="record"')}${button('Keep this draft and start another pair','data-measure-keep-new',true)}</div><p>The second button adds another kept version, then opens a new empty draft. It can keep the same draft again.</p><p>${esc(d.source.copy.reflection)}</p></section>`;}
function recovery(view){return `<section class="measuring-desk" data-measure-root><a href="#science">Back to Water Lab</a><h1 id="measure-title" tabindex="-1">The Measuring Desk</h1><p>This earlier measuring notebook cannot be opened here${view.reason==='ids-exhausted'?' because its entry numbers are exhausted':''}. Its entire original record stays in Grown-up notes and the download.</p><details data-measure-recovery><summary>Start a separate measuring notebook</summary><p>Keep the whole earlier record inside the new notebook. Download notes first if you want another copy.</p>${button('Confirm a separate notebook','data-measure-recover',true)}${button('Cancel','data-measure-recovery-cancel')}</details><p><a href="#notes">Grown-up notes and download</a></p><p id="measure-status" role="status" tabindex="-1"></p></section>`;}
export function measurementEntry(){return '<aside class="measure-entry"><h2>The Measuring Desk</h2><p>With an adult, record two readings from one real jug and compare only the numbers reported.</p><a class="secondary" href="#science/measure">Open the Measuring Desk</a></aside>';}
export function measuringDeskPage(state,explorerId){const view=core.measurementView(state);if(view.status==='recovery')return recovery(view);if(view.status==='absent'){const s=measurementSource();return `<section class="measuring-desk" data-measure-root><a href="#science">Back to Water Lab</a><h1 id="measure-title" tabindex="-1">${esc(s.title)}</h1>${method(s)}<p>${button('With an adult: start our local notebook','data-measure-start',true)} ${button('Print this method card','data-measure-print')}</p><p>${esc(s.copy.provenance)}</p><p id="measure-status" role="status" tabindex="-1"></p></section>`;}
 const d=view.draft,s=d.source,turn=d.page==='record'?recordTurn(d):d.page==='compare'?compareTurn(view):keptTurn(view);return `<section class="measuring-desk" data-measure-root><a href="#science">Back to Water Lab</a><h1 id="measure-title" tabindex="-1">${esc(s.title)}</h1><p>${esc(s.copy.intro)}</p><nav class="measure-tabs" aria-label="Measuring Desk turns">${[['record','Record'],['compare','Compare'],['kept','Keep']].map(([code,label],i)=>button(`${i+1}. ${label}`,`data-measure-page="${code}" aria-current="${d.page===code?'page':'false'}"`)).join('')}</nav>${turn}<details class="measure-method-fold"><summary>Method and safe materials</summary>${method(s,true)}</details><details data-measure-help ${d.support.includes('help')?'open':''}><summary>Help reading and comparing</summary><p>${esc(s.copy.help)}</p><p>${esc(s.copy.limit)}</p></details><div class="measure-support">${button('We worked together','data-measure-together')}${hearButton(`${s.title}. ${s.copy.intro} ${d.page==='record'?s.copy.unitNote:d.page==='compare'?s.copy.comparisonPrompt:s.copy.reflection}`,'Hear this turn')}</div>${history(view,state,explorerId)}<p>${button('Print this method card','data-measure-print')} <a href="#notes">Grown-up notes and download</a></p><p id="measure-status" role="status" tabindex="-1"></p></section>`;}
export function measuringDeskNotes(state){if(!Object.hasOwn(state,'measurementNotes'))return '';const v=core.measurementView(state);return `<details class="panel"><summary>Measuring Desk: adult-reported readings</summary><p>Adult-reported readings; physical accuracy and method unverified. Arithmetic compares entered numbers only.</p>${v.status==='recovery'?'<p>This earlier notebook format is unavailable here; the exact record remains below.</p>':`<p>${v.entries.length} readable kept versions; ${v.rawEntries.length} unavailable entries retained unchanged.</p>`}<pre>${esc(JSON.stringify(state.measurementNotes,null,2))}</pre></details>`;}

export function bindMeasuringDesk(state,ctx){const scope=document.querySelector('[data-measure-root]');if(!scope)return;let rootRef=state.measurementNotes,usedRecover=false,usedCompare=false,confirmRoot=null,confirmCompareRoot=null;const explorerId=ctx.explorerId?.()??null;
 const live=()=>scope.isConnected&&state.measurementNotes===rootRef&&(ctx.explorerId?.()??null)===explorerId&&location.hash==='#science/measure';
 const focus=selector=>ctx.focus?.(selector)||document.querySelector(selector)?.focus();
 const status=(msg,move=true)=>{const p=scope.querySelector('#measure-status');if(p){p.textContent=msg;if(move)p.focus();}};
 const refuse=(move=true)=>status('This change cannot be saved as a readable notes download. Earlier work is unchanged. Download notes or use a separate explorer.',move);
 const transact=(fn,{target='#measure-turn-title',rerender=true,refocus=true}={})=>{if(!live())return false;if(!core.commitMeasurement(state,fn,ctx.canExport)){refuse(refocus);return false;}rootRef=state.measurementNotes;ctx.save?.();if(rerender){ctx.render?.();if(refocus)focus(target);}return true;};
 scope.querySelector('[data-measure-start]')?.addEventListener('click',()=>transact(core.startMeasurement));
 const recover=scope.querySelector('[data-measure-recovery]');recover?.addEventListener('toggle',()=>{if(!recover.open)usedRecover=true;else{confirmRoot=state.measurementNotes;usedRecover=false;}});
 scope.querySelector('[data-measure-recovery-cancel]')?.addEventListener('click',()=>{usedRecover=true;recover.open=false;focus('#measure-title');});
 scope.querySelector('[data-measure-recover]')?.addEventListener('click',()=>{if(!live()||usedRecover||!recover.open||confirmRoot!==state.measurementNotes)return;usedRecover=true;transact(core.recoverMeasurement);});
 scope.querySelectorAll('[data-measure-page]').forEach(b=>b.addEventListener('click',()=>transact(c=>core.setMeasurementPage(c,b.dataset.measurePage))));
 scope.querySelectorAll('[data-measure-raw]').forEach(input=>input.addEventListener('input',()=>{if(!live())return;const key=input.dataset.measureRaw,old=core.measurementView(state).draft.raw[key],value=input.value,pos=input.selectionStart;if(!transact(c=>core.editMeasurementRaw(c,key,value),{rerender:false,refocus:false})){input.value=old;input.setSelectionRange(Math.min(pos,old.length),Math.min(pos,old.length));}}));
 scope.querySelectorAll('[data-measure-choice]').forEach(b=>b.addEventListener('change',()=>{if(!live())return;const old=core.measurementView(state).draft.choice;if(!transact(c=>core.chooseMeasurementRelation(c,b.dataset.measureChoice||null),{rerender:false,refocus:false}))scope.querySelectorAll('[data-measure-choice]').forEach(x=>x.checked=(x.dataset.measureChoice||null)===old);}));
 const compare=()=>{const d=core.measurementView(state).draft;if(core.parseMeasurement(d.raw.first)===null||core.parseMeasurement(d.raw.second)===null){status('Enter two mL readings from 0 to 2000 using digits and up to three decimal places. Uncertain entries can stay unfinished.',true);return;}if(d.comparison!==null&&!core.validMeasurementComparison(d.comparison)){const details=scope.querySelector('[data-measure-replace]');if(details){details.open=true;confirmCompareRoot=state.measurementNotes;usedCompare=false;focus('[data-measure-confirm-compare]');}return;}transact(c=>core.compareMeasurement(c),{target:'#measure-turn-title'});};
 scope.querySelector('[data-measure-compare]')?.addEventListener('click',()=>{if(live())compare();});
 const replace=scope.querySelector('[data-measure-replace]');replace?.addEventListener('toggle',()=>{if(!replace.open)usedCompare=true;});
 scope.querySelector('[data-measure-cancel-compare]')?.addEventListener('click',()=>{usedCompare=true;replace.open=false;focus('[data-measure-compare]');});
 scope.querySelector('[data-measure-confirm-compare]')?.addEventListener('click',()=>{if(!live()||usedCompare||!replace.open||confirmCompareRoot!==state.measurementNotes)return;usedCompare=true;transact(c=>core.compareMeasurement(c,true));});
 scope.querySelector('[data-measure-keep]')?.addEventListener('click',()=>transact(c=>!!core.keepMeasurement(c),{target:'#measure-turn-title'}));
 scope.querySelector('[data-measure-keep-new]')?.addEventListener('click',()=>transact(c=>!!core.keepMeasurement(c,true),{target:'#measure-turn-title'}));
 scope.querySelectorAll('[data-measure-history]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;const n=core.measurementView(state).entries.length,pages=Math.max(1,Math.ceil(n/8));historyTurn.page=Math.max(0,Math.min(pages-1,historyTurn.page+(b.dataset.measureHistory==='older'?1:-1)));ctx.render?.();focus('.measure-history summary');}));
 scope.querySelector('[data-measure-help] summary')?.addEventListener('click',e=>{const d=e.currentTarget.parentElement;if(d.open)return;e.preventDefault();if(transact(c=>core.useMeasurementSupport(c,'help'),{rerender:false})){d.open=true;focus('[data-measure-help] summary');}});
 scope.querySelector('[data-measure-together]')?.addEventListener('click',()=>transact(c=>core.useMeasurementSupport(c,'together'),{target:'[data-measure-together]'}));
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live()||state.measurementNotes!==undefined&&!transact(c=>core.useMeasurementSupport(c,'narrationRequested'),{rerender:false,refocus:false})){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));
 scope.querySelectorAll('[data-measure-print]').forEach(b=>b.addEventListener('click',()=>{if(!live())return;const methodFold=scope.querySelector('.measure-method-fold');if(methodFold)methodFold.open=true;window.print();}));
}
